package com.camerasmoothing;

import net.runelite.client.config.*;

@ConfigGroup("camerasmoothing")
public interface CameraSmoothingConfig extends Config
{
	@ConfigItem(
			keyName = "smoothRotation",
			name = "Rotation Smoothing",
			description = "Whether or not to smooth the camera rotation",
			position = 10
	)
	default boolean smoothRotation() { return true; }

	@Units("%")
	@Range(max = 100)
	@ConfigItem(
			keyName = "rotationSmoothness",
			name = "Rotation Smoothness",
			description = "How slowly the camera rotates (0-100%)",
			position = 11
	)
	default int rotationSmoothness()
	{
		return 60;
	}

	@ConfigItem(
			keyName = "smoothZoom",
			name = "Zoom Smoothing",
			description = "Whether or not to smooth the camera zoom",
			position = 100
	)
	default boolean smoothZoom() { return true; }

	@Units("%")
	@Range(max = 100)
	@ConfigItem(
			keyName = "zoomSmoothness",
			name = "Zoom Smoothness",
			description = "How slowly the camera zooms (0-100%)",
			position = 101
	)
	default int zoomSmoothness()
	{
		return 60;
	}
}

package com.camerasmoothing;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
        name = "Camera Smoothing"
)
public class CameraSmoothingPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private CameraSmoothingConfig config;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	private final int HALF_ROTATION = 8192;
	private final int FULL_ROTATION = 16384;

	private final int PITCH_INDEX = 0;
	private final int YAW_INDEX = 1;
	private final int SCROLL_INDEX = 2;
	//Made an array just in case a setter for camera pitch is ever added
	private int[] deltaCamera = new int[3];
	private int[] previousCamera = new int[3];

	private boolean zoomReady = false;

	@Override
	protected void startUp() {
		//migrates old smoothingSpeed to the independant config speeds
		String oldSmoothness = configManager.getConfiguration("camerasmoothing", "smoothingSpeed");
		if(oldSmoothness != null) {
			configManager.setConfiguration("camerasmoothing", "rotationSmoothness", oldSmoothness);
			configManager.setConfiguration("camerasmoothing", "zoomSmoothness", oldSmoothness);
			configManager.unsetConfiguration("camerasmoothing", "smoothingSpeed");
		}
	}

	private int lerp(int x, int y, float alpha) {
		return x+(int)((y-x)*alpha);
	}
	private int getSmallestAngle(int x, int y) {
		return mod(((y-x) + HALF_ROTATION), FULL_ROTATION) - HALF_ROTATION;
	}
	//https://stackoverflow.com/questions/1878907/how-can-i-find-the-difference-between-two-angles
	//This function was tested to produce results that were much more reasonable than the modulo operator
	public int mod(int a, int n) {
		return (int)(a - Math.floor(a/(float)n) * n);
	}
	private void applySmoothingToAngle(int index) {
		int deltaChange;
		int changed;
		int newDeltaAngle;

		// Leave yaw alone during cutscenes so the targets restore point isn't overridden
		if(index == YAW_INDEX && client.getVarbitValue(VarbitID.CUTSCENE_STATUS) != 0) {
			previousCamera[index] = client.getCameraYawTarget();
			deltaCamera[index] = 0;
			return;
		}

		// rendered yaw is smoother to follow, but it's only safe while the player is rotating
		boolean rotating = index == YAW_INDEX
				&& (client.isKeyPressed(KeyCode.KC_LEFT) || client.isKeyPressed(KeyCode.KC_RIGHT)
				|| client.getMouseCurrentButton() == 4 || client.getMouseCurrentButton() == 2);
		int targetAngle = index == YAW_INDEX
				? (rotating ? client.getCameraYaw() : client.getCameraYawTarget())
				: client.getCameraPitch();

		newDeltaAngle = getSmallestAngle(previousCamera[index], targetAngle);
		deltaCamera[index] += newDeltaAngle;

		//at 100% nothing would ever release and the camera locks up
		deltaChange = lerp(deltaCamera[index],0,(Math.min(99, config.rotationSmoothness())/100.0f));
		changed = previousCamera[index] + deltaChange;

		deltaCamera[index] -= deltaChange;
		if(index == YAW_INDEX) {
			client.setCameraYawTarget(changed);
		} else if(index == PITCH_INDEX) {
			client.setCameraPitchTarget(changed);
		}
		previousCamera[index] += deltaChange;
	}
	private void setZoom(int amount) {
		clientThread.invoke(()-> client.runScript(ScriptID.CAMERA_DO_ZOOM,amount,amount));
	}
	private void applySmoothingToZoom(int index) {
		int deltaChange;
		int changed;
		int newZoom;
		newZoom = client.getVarcIntValue(VarClientInt.CAMERA_ZOOM_RESIZABLE_VIEWPORT) - previousCamera[index];
		deltaCamera[index] += newZoom;

		//at 100% nothing would ever release and the camera locks up
		deltaChange = lerp(deltaCamera[index],0,Math.max(0,Math.min(0.99f,(config.zoomSmoothness()) / 100.0f)));
		changed = previousCamera[index] + deltaChange;

		deltaCamera[index] -= deltaChange;
		if(index == SCROLL_INDEX) {
			setZoom(changed);
		}
		previousCamera[index] += deltaChange;
	}
	@Subscribe
	public void onConfigChanged(ConfigChanged ev) {
		if(ev.getKey().equals("smoothRotation")) {
			if(config.smoothRotation()) {
				previousCamera[YAW_INDEX] = client.getCameraYawTarget();
				previousCamera[PITCH_INDEX] = client.getCameraPitch();
				deltaCamera[YAW_INDEX] = 0;
				deltaCamera[PITCH_INDEX] = 0;
			}
		} else if(ev.getKey().equals("smoothZoom")) {
			if(config.smoothZoom()) {
				previousCamera[SCROLL_INDEX] = client.getVarcIntValue(VarClientInt.CAMERA_ZOOM_RESIZABLE_VIEWPORT);
				zoomReady = true; // initialize zoomReady when smoothZoom toggled on
			}
		}
	}
	@Subscribe
	public void onBeforeRender(BeforeRender render) {
		if(client.getGameState() != GameState.LOGGED_IN) {
			return;
		}
		int deltaChange;
		int changed;
		int newDeltaAngle;

		if(config.smoothRotation()) {
			applySmoothingToAngle(PITCH_INDEX);
			applySmoothingToAngle(YAW_INDEX);
		}

		if(config.smoothZoom() && zoomReady) {
			applySmoothingToZoom(SCROLL_INDEX);
		}

	}

	@Subscribe
	public void onGameTick(GameTick event) {
		if(!zoomReady && client.getGameState() == GameState.LOGGED_IN) {
			int zoom = client.getVarcIntValue(VarClientInt.CAMERA_ZOOM_RESIZABLE_VIEWPORT);
			if(zoom > 0) {
				previousCamera[SCROLL_INDEX] = zoom;
				deltaCamera[SCROLL_INDEX] = 0;
				zoomReady = true;
			}
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		if(event.getGameState() == GameState.LOGGED_IN) {
			zoomReady = false;
		}
	}

	@Provides
	CameraSmoothingConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CameraSmoothingConfig.class);
	}
}

package com.camerasmoothing;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class CameraSmoothingTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(CameraSmoothingPlugin.class);
        RuneLite.main(args);
    }
}
